import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;import java.util.ArrayDeque;import java.util.Queue;import java.util.Arrays;import java.io.PrintWriter;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int N = Integer.parseInt(st.nextToken());int M = Integer.parseInt(st.nextToken());int Q = Integer.parseInt(st.nextToken());char[][] grid = new char[N][M];for (int i = 0; i < N; i++) {String line = br.readLine();for (int j = 0; j < M; j++) {grid[i][j] = line.charAt(j);}}st = new StringTokenizer(br.readLine());int startI = Integer.parseInt(st.nextToken()) - 1;int startJ = Integer.parseInt(st.nextToken()) - 1;int[][] dist = new int[N][M];for (int i = 0; i < N; i++) {Arrays.fill(dist[i], -1);}if (grid[startI][startJ] == 'O') {Queue<Integer> q = new ArrayDeque<Integer>();q.add(startI * M + startJ);dist[startI][startJ] = 0;int[] dr = {-1, 1, 0, 0};int[] dc = {0, 0, -1, 1};while (!q.isEmpty()) {int curr = q.poll();int r = curr / M;int c = curr % M;for (int i = 0; i < 4; i++) {int nr = r + dr[i];int nc = c + dc[i];if (nr >= 0 && nr < N && nc >= 0 && nc < M && grid[nr][nc] == 'O' && dist[nr][nc] == -1) {dist[nr][nc] = dist[r][c] + 1;q.add(nr * M + nc);}}}}PrintWriter out = new PrintWriter(System.out);for (int i = 0; i < Q; i++) {st = new StringTokenizer(br.readLine());int di = Integer.parseInt(st.nextToken()) - 1;int dj = Integer.parseInt(st.nextToken()) - 1;out.println(dist[di][dj]);}out.flush();out.close();}}